def compute(vars):
    current_maturities = vars["v1"]
    total_recourse_debt = vars["v2"]

    if total_recourse_debt == 0:
        return {"value": None, "trace": {
            "current_maturities": current_maturities,
            "total_recourse_debt": total_recourse_debt,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }}

    ratio = current_maturities / total_recourse_debt
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "current_maturities": current_maturities,
            "total_recourse_debt": total_recourse_debt,
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }
    }
